package com.airesumebuilder.feature.audit.service;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;import com.airesumebuilder.feature.audit.repository.AuditRepository;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.Map;import org.junit.jupiter.api.Test;
class AuditServiceTest{@Test void serializesAndAppendsStructuredAuditState(){AuditRepository repo=mock(AuditRepository.class);new AuditService(repo,new ObjectMapper()).record(2L,"Resume",9L,"CREATED",Map.of("safe",true));verify(repo).append(2L,"Resume",9L,"CREATED","{}","{\"safe\":true}");}@Test void recordsBeforeAndAfterState(){AuditRepository repo=mock(AuditRepository.class);new AuditService(repo,new ObjectMapper()).recordChange(2L,"Resume",9L,"UPDATED",Map.of("title","old"),Map.of("title","new"));verify(repo).append(2L,"Resume",9L,"UPDATED","{\"title\":\"old\"}","{\"title\":\"new\"}");}@Test void boundsPagination(){AuditRepository repo=mock(AuditRepository.class);when(repo.countForUser("a@b.com")).thenReturn(0L);var page=new AuditService(repo,new ObjectMapper()).listMine("a@b.com",-2,500);assertThat(page.page()).isZero();assertThat(page.size()).isEqualTo(100);verify(repo).listForUser("a@b.com",100,0);}}
